// Static catalog for the standalone Vercel storefront.
// Generated 2026-11-09 from the live Hermes store (getStorefront): 416 products
// with the verified per-product data (ref codes, colours, gallery views, sizes,
// detail lines, descriptions). Photos are NOT bundled here — see placeholders.ts.
// Settings are the live store settings at generation time; admin edits are kept
// in localStorage on top of these defaults (see api.ts).

export type ProductColor = { name: string; hex: string; available: boolean; pdpName?: string };
export type SizeOption = { label: string; available: boolean };

export type Product = {
  id: number; name: string; category: string; subcategory: string;
  theme: string; line: string; madeIn?: string; material: string; modelSize: string;
  metallicFinish: string; colors: ProductColor[];
  price: number; priceLabel: string; status: string; description: string;
  story: string; tone: string; glyph: string; sortOrder: number; fwPos?: number;
  refCode: string; galleryViews: string[]; applePay: boolean; configUrl?: string;
  sizeOptions: SizeOption[]; accordions: string[]; shippingDelay: string;
  detailLines: string[];
  // Per-product overrides (optional; only the Cashmere coat uses them so far):
  // colorwayRefs — refCodes of sibling colourway rows (PDP colour thumbs navigate to them);
  // partnerIds / exploreIds — exact "The Perfect Partner" / "Keep exploring" rows;
  // accordionBodies — verbatim accordion bodies; lines starting "## " are subheadings,
  // lines starting "• " are bullets; defaultSize — size pre-selected on landing.
  colorwayRefs?: string[]; partnerIds?: number[]; exploreIds?: number[];
  accordionBodies?: Record<string, string[]>; defaultSize?: string;
};

export type Settings = {
  storeName: string; phone: string; heroTitle: string; heroText: string;
  shipTo: string; deliveryText: string; returnsText: string;
  paymentMethods: string; bgColor: string; serviceHours: string;
  logoMode: string; logoUrl: string;
  flagshipStore: string; shipToCountries: string; newsletterText: string;
  newsletterSuccess: string; copyrightText: string;
  serviceDeliveryBody: string; serviceReturnsBody: string;
  servicePaymentBody: string; chatEnabled: boolean; chatWelcome: string;
  legalLinksJson: string;
};
